// --- Enchantment Definitions ---
// Realm-sorted controls; see Calculator/CLAUDE.md for the layout each block has to produce.

const ENCHANTMENT_DEFS = [
  // All versions: Received bonuses on top, then Elements, then Chaos Channels.
  { key: 'combatSummoned', label: 'Combat Summoned', type: 'bool', alwaysVisible: true, group: 'Enchantments', subgroup: '_All versions bools',
    tooltip: 'Encounter condition: the unit was summoned during combat.\nCoM1/CoM2/Warlord: the live unit is Fantastic.\nCoM1: Paladins become Life; Centaurs and Catapult become Nature.\nCoM2: Paladins become Life (Call to Arms).' },
  { key: 'resistanceToAll', label: 'Received res. to all', type: 'num', match: 'ResistancetoAll', group: 'Enchantments', subgroup: 'All versions', tooltip: '+X resistance.' },
  { key: 'holyBonus', label: 'Received holy bonus', type: 'num', match: 'HolyBonus', group: 'Enchantments', subgroup: 'All versions', tooltip: '+X melee attack, defense, and resistance.\nCoM 1 & 2 & Warlord: Also +X ranged, thrown, and breath attack.' },
  { key: 'elemArmor', label: 'Elements', type: 'select', options: [['none','None'],['resistElements','Resist Elem.'],['elementalArmor','Elem. Armor']], group: 'Enchantments', subgroup: 'All versions', realm: 'nature', tooltip: 'Resist Elements:\nDefense bonus vs magical ranged and breath attacks; resistance\nbonus vs Stoning Touch and Stoning Gaze.\nMoM 1.31 & 1.60: +3. Defense applies to Chaos/Nature magical\nranged, breath, Immolation, and Wall of Fire.\nCoM 1: +4 defense vs all magical ranged, breath, Immolation,\nand Wall of Fire.\nCoM 2 & Warlord: +4 defense vs all magical ranged and breath.\nElemental Armor:\nMoM 1.31 & 1.60: +10 defense vs Chaos/Nature magical ranged,\nbreath, Immolation, and Wall of Fire; +10 resistance vs Stoning\nTouch and Stoning Gaze.\nCoM 1: +12 defense vs all magical ranged, breath, Immolation,\nand Wall of Fire.\nCoM 2 & Warlord: +12 defense vs all magical ranged and breath.' },
  ...realmLinear([
    { key: 'prayer', label: 'Prayer', type: 'bool', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: "+10% To Hit, +10% To Block, +1 resistance.\nMoM 1.31: Enemy melee attacks suffer −10% To Hit.\nMoM 1.31 & 1.60, CoM 1 & 2: Does not stack with High Prayer\n(High Prayer supersedes it).\nWarlord: Active alongside High Prayer. When both are up, Prayer's\nTo Hit and To Block are replaced by +1 melee and +1 defense, so\nits added contribution is +1 melee, +1 defense, +1 resistance." },
    { key: 'highPrayer', label: 'High Prayer', type: 'bool', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: '+2 melee attack, +2 defense, +3 resistance,\n+10% To Hit, +10% To Block.\nMoM 1.31 & 1.60, CoM 1 & 2: Supersedes Prayer (not cumulative).\nMoM 1.31: Enemy melee attacks suffer −10% To Hit.\nWarlord: Stacks with Prayer. Combined total: +3 melee, +3 defense,\n+4 resistance, +10% To Hit, +10% To Block.' },
    { key: 'trueSight', label: 'True Sight', type: 'bool', match: 'TrueSight', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: 'Grants Illusion Immunity.\nWarlord: +5% ranged, thrown, and breath To-Hit.' },
    { key: 'bless', label: 'Bless', type: 'bool', match: 'Bless', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: "+X defense vs Chaos/Death attacks and +X resistance vs Death Gaze,\nDeath Touch, Life Steal, Cause Fear, and Destruction.\nMoM 1.31 & 1.60: +3 defense, +3 resistance. Defense applies to\nChaos/Death creature melee, fire/lightning breath, magical Chaos\nranged, Chaos/Death gazes, Immolation, and Wall of Fire.\nCoM 1: +5 defense, +5 resistance. Defense applies only to\nfire/lightning breath and Chaos/Death gazes — not to melee,\nthrown, ranged, Immolation, or Wall of Fire.\nCoM 2: +5 defense, +5 resistance.\nWarlord: +7 defense, +4 resistance.\nCoM 2 & Warlord: Defense applies only to Immolation and Wall of\nFire, the two Chaos-realm spell attacks. No unit attack reaches\nit — not melee, thrown, breath, ranged, or gaze." },
    { key: 'invulnerability', label: 'Invulnerability', type: 'bool', match: 'Invulnerability', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: 'Grants Weapon Immunity.\nReduces incoming damage by 2 per defense roll.\nDoes not reduce Doom damage.' },
    { key: 'holyWeapon', label: 'Holy Weapon', type: 'bool', match: 'HolyWeapon', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: '+10% To Hit on melee, missile, boulder, and thrown attacks.\nNegates Weapon Immunity (upgrades a normal weapon to magic).\nMoM 1.31 bug: Does not affect thrown attacks.' },
    { key: 'lionheart', label: 'Lionheart', type: 'bool', match: 'Lionheart', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: '+3 melee, missile, and boulder attack; +3 resistance.\nMoM 1.31 & 1.60: also +3 thrown attack; +3 HP per figure.\nCoM 1 & 2 & Warlord: +floor(8/figures) HP per figure.\nWarlord: with Blaze of Glory the ranged +3 becomes a Thrown attack,\neven on a unit that has no ranged attack.' },
    { key: 'holyArmor', label: 'Holy Armor', type: 'bool', match: 'HolyArmor', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: 'MoM 1.31 & 1.60: +2 defense.\nCoM 1 & 2 & Warlord: +2 defense if defense ≤ 5;\n+10% To Block if defense > 5.' },
    { key: 'charmOfLife', label: 'Charm of Life', type: 'bool', match: 'CharmOfLife', group: 'Enchantments', subgroup: '_All versions bools', realm: 'life', tooltip: '+25% HP per figure (minimum +1 HP per figure).' },
    { key: 'fear', label: 'Cloak of Fear', type: 'bool', match: 'CauseFear', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: "Grants Cause Fear.\nOpponents with Magic Immunity or Righteousness are unaffected.\nFor each opponent figure: Resist or freeze for the melee exchange.\nMoM 1.31 & 1.60: Death Immunity skips the roll;\nno resistance modifier.\nMoM 1.31 bug 1: Defender's Cause Fear never fires — only the\nattacker's does.\nMoM 1.31 bug 2: Each of the defender's failed rolls also fears one\nattacker figure (self-fear), bypassing immunity.\nCoM 1: Death Immunity skips the −3 roll.\nCoM 2: Intrinsic/base Death Immunity skips the −3 roll;\nrecalculation-only Death Immunity still rolls.\nWarlord: Intrinsic/base Death Immunity skips the −3 roll;\nrecalculation-only Death Immunity still rolls." },
    { key: 'undead', label: 'Undead', type: 'bool', match: 'Undead', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'Unit becomes a fantastic Death creature.\nMoM 1.31: Grants Death Immunity.\nMoM 1.31 bug: Should also have granted Cold, Poison, and Illusion Immunity.\nMoM 1.60: Grants Death, Cold, Poison, and Illusion Immunity.\nCoM 1 & 2 & Warlord: Grants Death, Cold, and Illusion Immunity.' },
    { key: 'animated', label: 'Animate Dead', type: 'bool', match: 'Animated', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'Unit becomes undead (fantastic Death creature).\nMoM 1.31: Grants Death Immunity.\nMoM 1.31 bug: Should also have granted Cold, Poison, and Illusion Immunity.\nMoM 1.60: Grants Death, Cold, Poison, and Illusion Immunity.\nCoM 1 & 2 & Warlord: Grants Death, Cold, and Illusion Immunity as well as\nthe Animated buff: +1 melee, ranged, thrown, breath, and defense;\n+10% To Hit; Weapon Immunity. CoM2/Warlord Gaze is unchanged.' },
    { key: 'blackSleep', label: 'Black Sleep', type: 'bool', match: 'BlackSleep', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'Units with Magic Immunity are unaffected.\nSleeping unit cannot attack or counterattack.\nIncoming conventional attacks skip to-hit and defense rolls and deal\nfull strength as exact damage (maximum damage). Ranged penalties and\nmissile immunity are ignored.\nThe damage is not halved (unlike the Doom ability).' },
    { key: 'blackPrayer', label: 'Black Prayer', type: 'bool', match: 'BlackPrayer', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: '−1 to melee, ranged, thrown, and breath attack;\n−1 defense; −2 resistance.\nCoM2/Warlord: Independent Gaze fields are unchanged.' },
    { key: 'raiseDead', label: 'Raise Dead', type: 'bool', match: 'RaiseDead', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'MoM 1.31 & 1.60: No effect on combat stats; the revived unit\nretains its original type and realm.\nCoM 1 & 2 & Warlord: Revived unit becomes an unaligned fantastic\ncreature.' },
    { key: 'weakness', label: 'Weakness', type: 'bool', match: 'Weakness', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'Units with Magic Immunity are unaffected.\nMoM 1.31: −2 melee, −2 missile.\nMoM 1.31 bug: Thrown is unaffected.\nMoM 1.60: −2 melee, −2 missile, −2 thrown.\nMoM: Boulder and magic ranged are unaffected.\nCoM 1 & 2: −3 melee, −3 thrown, −3 to any ranged attack.\nWarlord: as CoM 2, plus −3 breath.\nBreath and gaze are unaffected except in Warlord.' },
    { key: 'wraithForm', label: 'Wraith Form', type: 'bool', match: 'WraithForm', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'Grants Weapon Immunity and Non-Corporeal.\nCoM 1 & 2 & Warlord: Attacks bypass enemy Weapon Immunity.' },
    { key: 'eternalNight', label: 'Eternal Night', type: 'bool', match: 'EternalNight', group: 'Enchantments', subgroup: '_All versions bools', realm: 'death', tooltip: 'Side owns the global enchantment.\nMoM 1.31/1.60 and CoM 1: All combats are under Darkness at normal strength.\nCoM 2 & Warlord: Death attack/Armor bonuses are doubled.\nLife penalties stay at normal strength.\nCoM 1 & 2 & Warlord: Enemy non-Death units lose 1 resistance.\nWarlord: Enemy non-Death units also suffer −2 ranged attack strength\n(missile, boulder, and magic ranged; thrown and breath unaffected).' },
    { key: 'ccDefense', label: 'CC: +Defense', type: 'bool', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Unit permanently becomes a fantastic Chaos creature.\n+3 defense.\nMoM 1.31 bug: Defense applied twice in combat (net +6).' },
    { key: 'ccFireBreath', label: 'CC: +Fire Breath', type: 'bool', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Unit permanently becomes a fantastic Chaos creature.\nMoM 1.31: A base None/Thrown slot at most 3 becomes Fire Breath 2.\nMoM 1.31 bug: that slot is assigned again late in combat,\ndiscarding node, Black Prayer and Mind Storm changes to it.\nMoM 1.60: A base None/Thrown slot at most 0 becomes Fire Breath 2.\nCoM 1: A base None/Thrown slot at most 0 becomes Fire Breath 4.\nCoM 2 & Warlord: Adds 4 to the independent Fire Breath channel;\nranged, Thrown, Lightning Breath, and Gaze remain.' },
    { key: 'ccFlight', label: 'CC: +Flight', type: 'bool', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Unit permanently becomes a fantastic Chaos creature.\nNot modeled: flight (movement and targeting).' },
    { key: 'immolation', label: 'Immolation', type: 'bool', match: 'Immolation', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Fire area attack each melee phase, hitting all opponent figures.\nOpponents with Fire Immunity, Magic Immunity, or Righteousness\nare unaffected.\nMoM 1.31 & 1.60: Strength 4.\nMoM 1.31 bug: Also fires alongside ranged attacks.\nCoM 1 & 2 & Warlord: Strength 10.\nNot modeled: web burning, freeze prevention.' },
    { key: 'flameBlade', label: 'Flame Blade', type: 'bool', match: 'FlameBlade', group: 'Enchantments', subgroup: '_All versions bools', exceptVersions: ['com2_warlord_'], realm: 'chaos', tooltip: 'Bypasses Weapon Immunity.\nMoM 1.31 & 1.60: +2 melee, thrown and missile attack.\nCoM 1 & 2: +3 melee and +2 missile.' },
    { key: 'shatter', label: 'Shatter', type: 'bool', match: 'Shatter', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'All melee, ranged, thrown, and breath attack strengths reduced to 1.\nAffects normal units and heroes only.\nUnits with Magic Immunity are unaffected.\nWarlord: Affects any unit.' },
    { key: 'warpAttack', label: 'Warp: Attack', type: 'bool', match: 'WarpAttack', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Units with Magic Immunity are unaffected.\nMelee attack halved.\nCoM 1 & 2 & Warlord: Ranged, thrown and breath attacks also halved.\nCoM 1: Gaze attacks too — they share the ranged stat.\nCoM 1 signed halves round down; CoM 2/Warlord truncate toward zero.\nCoM 1: Halves before Darkness, Supreme Light and Tactician,\nwhich are added at full value afterwards.' },
    { key: 'warpDefense', label: 'Warp: Defense', type: 'bool', match: 'WarpDefense', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Units with Magic Immunity are unaffected.\nDefense halved.\nCoM 1 & 2 & Warlord: Defense reduced to one-third instead.\nCoM 1 signed thirds truncate toward zero.\nCoM 1: Reduces before Darkness, Supreme Light and Tactician,\nwhich are added at full value afterwards.' },
    { key: 'warpResist', label: 'Warp: Resist', type: 'bool', match: 'WarpResist', group: 'Enchantments', subgroup: '_All versions bools', realm: 'chaos', tooltip: 'Units with Magic Immunity are unaffected.\nResistance set to 0.\nResist Magic still adds +5 on top.\nCoM 1: Zeroes before Darkness, Tactician and Eternal Night,\nwhich are added at full value afterwards.' },
    { key: 'ironSkin', label: 'Iron Skin', type: 'bool', match: 'IronSkin', group: 'Enchantments', subgroup: '_All versions bools', realm: 'nature', tooltip: '+5 defense.\nSupersedes Stone Skin (does not stack).' },
    { key: 'invisibility', label: 'Invisibility', type: 'bool', match: 'Invisibility', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'Grants Invisible: cannot be targeted by ranged attacks\n(unless the opponent has Illusion Immunity).\nMoM 1.31 & 1.60: Opponents attacking it suffer −10% To Hit on\nmelee and ranged, unless they have Illusion Immunity.\nCoM 1, CoM2 & Warlord: Instead grants a 20% per-hit Blur chance.\nCoM 1 stacks with unit Blur to 30%.\nCoM2 stacks with tactical defender Card B\'s army Blur to 30%;\nWarlord 40%. Opponent Illusion Immunity negates the reduction.' },
    { key: 'magicImmunity', label: 'Magic Immunity', type: 'bool', match: 'MagicImmunity', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'Immunity to magic ranged attacks, Immolation damage, Wall of Fire, Death Gaze,\nDeath Touch, Life Steal, Cause Fear, Stoning, Dispel Evil, and Exorcise.\nAlso negates the curses Weakness, Black Sleep, Shatter, Vertigo,\nWarp Creature, Mind Storm, Nausea, and Temporal Twist.\nMoM only: Also protects against Fire Breath and Lightning Breath.' },
    { key: 'guardianWind', calcKey: 'missileImmunity', label: 'Guardian Wind', type: 'bool', match: 'MissileImmunity', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'Grants Missile Immunity.' },
    { key: 'blur', label: 'Blur', type: 'bool', match: 'Blur', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'MoM 1.31, MoM CP 1.60, and CoM 1: unit-owned enchantment.\nEach incoming hit may be negated before defense rolls; Doom and\nspell damage are unaffected.\nMoM 1.31 & 1.60: 10% per hit.\nMoM 1.31 bug 1: Each negation skips the next roll; at most\nceil(hits / 2) are negated.\nMoM 1.31 bug 2: The unit\'s own Illusion Immunity disables its Blur;\nthe opponent\'s Illusion Immunity is ignored.\nMoM 1.60 & CoM 1: Opponent Illusion Immunity negates Blur.\nCoM 1: 20% per hit; stacks with Invisibility to 30%.\nCoM2 & Warlord: 20% per hit; stacks with Invisibility to 30%\n(CoM2) or 40% (Warlord). This checkbox records whether this unit\'s\narmy has Blur. Card B is the tactical defender, so only Card B\'s\nBlur is used for this exchange, including Card B\'s counterattack.\nCard A\'s value is retained for Swap. Invisibility remains unit-owned.' },
    { key: 'resistMagic', label: 'Resist Magic', type: 'bool', match: 'ResistMagic', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: '+5 resistance vs Cause Fear, Death Gaze, Life Steal, Stoning Gaze,\nStoning Touch, Dispel Evil, and Exorcise.\nDoes not affect Poison Touch.' },
    { key: 'haste', label: 'Haste', type: 'bool', match: 'Haste', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'Melee, thrown, breath, and ranged attacks are performed twice.\nMoM 1.31 & 1.60: Counter-attacks are also performed twice.\nMoM 1.31: Caster magical ranged needs at least 7 mana.\nMoM 1.31: Hero magical ranged is not repeated.\nMoM 1.60: Caster magical ranged needs at least 6 mana.\nCoM 1 & 2 & Warlord: Counter-attacks are performed once.\nNot modeled: movement, ammunition, mana consumption.' },
    { key: 'vertigo', label: 'Vertigo', type: 'bool', match: 'Vertigo', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'Penalizes the cursed unit on To Hit, plus To Block (CoM)\nor defense (MoM).\nTo Hit affects melee, ranged, thrown, breath, and gaze attacks.\nDefense/To Block also affects Immolation and Wall of Fire.\nMoM 1.31 & 1.60: −20% To Hit, −1 defense.\nCoM 1: −30% To Hit, −10% To Block.\nCoM 2 & Warlord: −25% To Hit, −7% To Block.' },
    { key: 'mindStorm', label: 'Mind Storm', type: 'bool', match: 'MindStorm', group: 'Enchantments', subgroup: '_All versions bools', realm: 'sorcery', tooltip: 'Units with Illusion or Magic Immunity are unaffected.\nAttack, defense, and resistance penalties on the cursed unit.\nMoM 1.31 & 1.60: −5 melee, ranged, thrown, breath, defense,\nand resistance.\nCoM 1: −3 melee; −5 shared ranged/thrown/breath, defense,\nand resistance.\nCoM 2 & Warlord: −3 melee; −5 conventional ranged, Thrown,\ndefense, and resistance. Breath and Gaze are unchanged.' },
  ]),
  // Enchantments — MoM only (removed in CoM) — visual order: life → death → chaos → nature
  ...realmLinear([
    { key: 'righteousness', label: 'Righteousness', type: 'bool', match: 'Righteousness', group: 'Enchantments', subgroup: 'MoM only', realm: 'life', tooltip: 'Versions: MoM 1.31 & 1.60\nImmune to Chaos magical ranged, Fire Breath, Lightning Breath,\nImmolation, and Wall of Fire.\nImmune to Cause Fear, Life Steal, Death Gaze, and Death Touch.' },
    { key: 'berserk', label: 'Berserk (MoM)', type: 'bool', match: 'Berserk', group: 'Enchantments', subgroup: 'MoM only', realm: 'death', tooltip: 'Versions: MoM 1.31 & 1.60\nDoubles melee attack, after every other unit enchantment but\nbefore the combat enchantments (Prayer, Darkness, Metal Fires).\nSets defense to 0; no other bonus can raise it.' },
    { key: 'blackChannels', label: 'Black Channels', type: 'bool', match: 'BlackChannels', group: 'Enchantments', subgroup: 'MoM only', realm: 'death', tooltip: 'Versions: MoM 1.31 & 1.60\n+2 melee, +1 ranged/thrown/breath/gaze, +1 defense,\n+1 resistance, +1 HP per figure.\nUnit becomes a fantastic Death creature.\nGrants Cold, Illusion, Poison, and Death Immunity.' },
    { key: 'metalFires', label: 'Metal Fires', type: 'bool', match: 'MetalFires', group: 'Enchantments', subgroup: 'MoM only', realm: 'chaos', tooltip: 'Versions: MoM 1.31 & 1.60\nNon-Fantastic units only.\n+1 melee, +1 missile, +1 thrown.\nUpgrades normal weapons to magic (bypasses Weapon Immunity).\nDoes not stack with Flame Blade.' },
    { key: 'eldritchWeapon', label: 'Eldritch Weapon', type: 'bool', match: 'EldritchWeapon', group: 'Enchantments', subgroup: 'MoM only', realm: 'chaos', tooltip: "Versions: MoM 1.31 & 1.60\nTarget's To Block reduced by 10% against this unit's melee,\nmissile, and thrown attacks.\nUpgrades a normal melee weapon to magic (melee bypasses Weapon\nImmunity); ranged/thrown attacks stay non-magical." },
    { key: 'giantStrength', label: 'Giant Strength', type: 'bool', match: 'GiantStrength', group: 'Enchantments', subgroup: 'MoM only', realm: 'nature', tooltip: 'Versions: MoM 1.31 & 1.60\n+1 melee and +1 thrown.' },
    { key: 'stoneSkin', label: 'Stone Skin', type: 'bool', match: 'StoneSkin', group: 'Enchantments', subgroup: 'MoM only', realm: 'nature', tooltip: 'Versions: MoM 1.31 & 1.60\n+1 defense.\nDoes not stack with Iron Skin.' },
  ]),
  // Enchantments — CoM, CoM2 & Warlord (added in CoM, kept in CoM2) — visual order: life → death → chaos → nature → sorcery
  ...realmLinear([
    { key: 'guardian', label: 'Guardian retort', type: 'bool', match: 'Guardian', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', tooltip: 'Versions: CoM 1 & 2 & Warlord\n+1 Resistance, +10% To Hit, +10% To Block.' },
    { key: 'tactician', label: 'Tactician retort', type: 'bool', match: 'Tactician', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', tooltip: 'Versions: CoM 1 & 2 & Warlord\nCoM 1 & 2: Non-hero units gain +1 defense.\nHeroes instead gain +2 defense, +2 resistance, +2 melee, and +2 ranged.\nCoM 1: Its shared ranged slot also reaches Thrown, Breath, and Gaze.\nCoM 2: Only conventional ranged receives the secondary-attack bonus.\nWarlord: All units gain +1 defense (no hero distinction).\nTeleporting units gain First Strike.\nNon-Corporeal units gain Negate First Strike.' },
    { key: 'supremeLight', label: 'Supreme Light', type: 'bool', match: 'SupremeLight', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 1 & 2 & Warlord\nCoM 1 eligibility: live magical ranged, Life race, Caster/mana,\nFocus Magic, or base magical ranged. +2 melee unconditionally;\n+2 to any positive shared ranged/thrown/breath/gaze attack;\nDefense += signed trunc(Resistance / 3).\nCoM 2 & Warlord: applies to Life fantastic creatures and Caster\nunits; +2 existing melee and conventional ranged;\nDefense += floor(max(Resistance, 0) / 3).' },
    { key: 'endurance', label: 'Endurance', type: 'bool', match: 'Endurance', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 1 & 2 & Warlord\nCoM 1: +2 defense.\nCoM 2 & Warlord: +floor(4 / figures) HP per figure, minimum +1.' },
    { key: 'bloodLust', label: 'Blood Lust', type: 'bool', match: 'BloodLust', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'death', tooltip: 'Versions: CoM 1 & 2 & Warlord\nCoM 1 & 2: Unit becomes undead (fantastic Death creature) and\ngains Death, Cold, and Illusion Immunity.\nWarlord: Does not turn the unit undead; no immunities granted.\nCoM 1: Doubles melee attack vs Normal and Hero targets.\nCoM 2 & Warlord: Doubles melee and Thrown attacks vs\nnon-Fantastic targets.' },
    { key: 'mysticSurge', label: 'Mystic Surge', type: 'bool', match: 'MysticSurge', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'chaos', tooltip: "Versions: CoM 1 & 2 & Warlord\n+2 defense, −2 resistance.\nOpponent's To Block reduced by 10%.\nUnit becomes an unaligned fantastic creature.\nNot modeled: the granted random enchantments." },
    { key: 'blazingMarch', label: 'Blazing March', type: 'bool', match: 'BlazingMarch', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'chaos', tooltip: 'Versions: CoM 1 & 2 & Warlord\nCoM 1 & 2: +3 melee and +3 missile attack.\nWarlord: also +3 thrown attack.\nCoM 1: boosted melee and missile bypass Weapon Immunity.\nCoM 2 & Warlord: sets the unit-wide Magic Weapon flag, so all\nphysical attacks bypass Weapon Immunity.' },
    { key: 'survivalInstinct', label: 'Survival Instinct', type: 'bool', match: 'SurvivalInstinct', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'nature', tooltip: 'Versions: CoM 1 & 2 & Warlord\nApplies to fantastic creatures.\n+1 defense, +2 resistance, +10% To Hit.' },
    { key: 'landLinking', label: 'Land Linking', type: 'bool', match: 'LandLinking', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', exceptVersions: ['com2_warlord_'], realm: 'nature', tooltip: 'Versions: CoM 1 & 2\nApplies to fantastic units.\n+2 defense, +2 melee, and +2 breath attack.' },
    { key: 'focusMagic', label: 'Focus Magic', type: 'bool', match: 'FocusMagic', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'sorcery', tooltip: 'Versions: CoM 1 & 2 & Warlord\nMagical ranged or breath attack present: +3 strength.\nCoM 1: a gaze takes that +3 too, and no attack is created beside it.\nCoM 2 & Warlord — Doom Gaze present: +3 doom damage.\nThrown / missile / boulder attack: converted into a Sorcery\nmagical ranged attack. CoM 1 raises it to a minimum of 3;\nCoM 2 and Warlord preserve its positive strength.\nNo conventional ranged or Thrown to convert: gains a strength-3\nSorcery magical ranged attack. CoM 2 & Warlord create it beside\nan existing Breath or Gaze as well.\nCoM 2 & Warlord: strength changes occur before Warp Attack.\nWarlord: Moves an existing general/card Stoning or Death Touch\nto melee and Thrown.' },
    { key: 'realmWard', label: 'Realm Ward', type: 'select', options: [['none','None'],['nature','Nature'],['sorcery','Sorcery'],['chaos','Chaos'],['life','Life'],['death','Death']], group: 'Enchantments', subgroup: 'CoM only', realm: 'sorcery', tooltip: 'Versions: CoM 1\nSelect the defending city ward.\nA matching Fantastic creature loses 20% To Hit,\n3 Defense, and 3 Resistance.' },
    { key: 'spellLock', label: 'Spell Lock', type: 'bool', match: 'SpellLock', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'sorcery', tooltip: 'Versions: CoM 1 & 2 & Warlord\nBlocks Exorcise against this Fantastic unit.\nIt adds no Resistance of its own.\nWarlord: a Wanderer already carrying it is refused the strayed\nMarionette package, so it loses that melee, armor and resistance.' },
  ]),
  // Enchantments — CoM2 & Warlord — select first, then bools interleaved for life → death → chaos → sorcery
  { key: 'discipline', label: 'Discipline', type: 'select', options: [['none','None'],['overland','Overland'],['combat','Combat']], match: 'Discipline', group: 'Enchantments', subgroup: 'CoM2 & Warlord', exceptVersions: ['com2_warlord_'], realm: 'life', tooltip: 'Versions: CoM 2\nCannot be cast on a hero, or on a unit that is fantastic on\nits permanent record.\n+1 defense.\nRegular or higher: +2 defense.\nVeteran or higher: +2 defense, +1 melee, +1 physical ranged.\nElite or higher, cast in combat: also Negate First Strike.\nNot modeled: movement bonus (overland cast, Elite+).' },
  { key: 'disciplineWarlord', calcKey: 'discipline', label: 'Discipline', type: 'select', options: [['none','None'],['overland','Overland'],['combat','Combat']], match: 'Discipline', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nArcane unit ability, also granted permanently by Military Drilling.\nCannot be cast on a unit that is fantastic on its permanent\nrecord. Heroes can receive it.\n+1 defense.\nRegular or higher: +2 defense.\nVeteran or higher: +2 defense, +1 melee, +1 physical ranged.\nElite or higher, cast in combat: also Negate First Strike.\nNot modeled: movement bonus (overland cast, Elite+).' },
  { key: 'breakthrough', label: 'Breakthrough', type: 'select', options: [['none','None'],['melee','+1mel'],['meleeDef','+1mel/+1def']], match: 'Breakthrough', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'chaos', tooltip: 'Versions: CoM 2 & Warlord\nPermanent normal unit: +1 melee.\nNon-corporeal or temporary unit: +1 melee, +1 defense.\nNot modeled: Wall Crusher.' },
  { key: 'spellWard', label: 'Spell Ward realm', type: 'select', options: [['none','None'],['nature','Nature'],['sorcery','Sorcery'],['chaos','Chaos'],['life','Life'],['death','Death']], group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'sorcery', tooltip: 'Versions: CoM 2 & Warlord\nSelect the defending city ward.\nApplies to a unit of the ward\'s realm, Fantastic or not.\nA matching unit loses 20% To Hit, 3 defense, and 3 resistance.' },
  { key: 'guidingBeaconAura', label: 'Guiding Beacon aura', type: 'num', min: 0, max: 99, group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'sorcery', tooltip: 'Versions: CoM 1 & 2, Warlord\nEnter the strongest friendly side-maximum aura value.\nAdds that value to a conventional ranged attack.\nThrown, Breath, and Gaze are unchanged.' },
  { key: 'prayermasterAura', label: 'Prayermaster aura', type: 'num', min: 0, max: 99, group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 2 & Warlord\nEnter the strongest friendly aura value.\nAdds that value to Resistance.\nCompetes by maximum with Resistance to All rather than stacking.' },
  { key: 'divineBarrierAura', label: 'Divine Barrier aura', type: 'num', min: 0, max: 99, group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 1 & 2, Warlord\nEnter the strongest friendly side-maximum aura value.\nAdds that value to Defense.' },
  { key: 'soulLinkerAura', label: 'Soul Linker aura', type: 'num', min: 0, max: 99, group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 1 & 2, Warlord\nEnter the strongest friendly side-maximum aura value.\nFantastic units gain To Hit and To Block.\nCoM 1: To Hit gains ceil(value / 2); To Block gains\nfloor(value / 2). CoM 2 & Warlord: both gain the full value.' },
  { key: 'leadershipAura', label: 'Leadership aura', type: 'num', min: 0, max: 99, group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 2 & Warlord\nEnter the strongest friendly aura value.\nNormal units gain the full value to existing melee and\ntrunc(value / 2) to non-magical conventional ranged.\nThrown, Breath, Gaze, and magical ranged are unchanged.' },
  ...realmLinear([
    { key: 'heavenlyLight', label: 'Heavenly Light / Guardian node', type: 'bool', match: 'HeavenlyLight', group: 'Enchantments', subgroup: 'CoM, CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 1 & 2 & Warlord\nEnable for a unit belonging to the defending army in a\nHeavenly Light city or on a friendly Guardian Spirit node.\nSelect on either card by army membership; the card labels describe\nthe current exchange role, not persistent army membership.\nCoM 1: city combat only, and only for the defending side; there is\nno node path.\n+1 Defense and Resistance; +1 to a positive melee attack and to a\npositive shared ranged/thrown/breath/gaze attack.\nGrants Magic Weapon. A unit carrying no weapon material also gains\n+10% To Hit on melee, and on a positive missile, boulder or Thrown\nattack.\nNot modeled: the unit-type ceiling that also suppresses that\nTo Hit bonus.\nCoM 2 & Warlord: +1 Defense and Resistance; +1 existing base melee\nand current conventional ranged. Grants Magic Weapon. Eligible\nnormal units also gain +10% To Hit on melee, physical ranged, and\nThrown.' },
    { key: 'darkForce', label: 'Dark Force', type: 'bool', match: 'DarkForce', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'death', tooltip: 'Versions: CoM 2 & Warlord\n+10% To Hit and +10% To Block.' },
    { key: 'badMoon', label: 'Bad Moon', type: 'bool', match: 'BadMoon', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'death', tooltip: 'Versions: CoM 2 & Warlord\nIn combat, base non-Fantastic units lose 3 Resistance.' },
    { key: 'goodMoon', label: 'Good Moon', type: 'bool', match: 'GoodMoon', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'life', tooltip: 'Versions: CoM 2 & Warlord\nBase non-Fantastic units gain +1 Defense and +1 to\npositive current melee and conventional ranged attacks.' },
    { key: 'natureConjunction', label: 'Nature Conjunction', type: 'bool', match: 'NatureConjunction', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'nature', tooltip: 'Versions: CoM 2 & Warlord\nBase Fantastic units gain +2 Defense, +2 Resistance, and\n+2 to positive current melee and conventional ranged attacks.' },
    { key: 'destiny', label: 'Destiny', type: 'bool', match: 'Destiny', group: 'Enchantments', subgroup: 'CoM2 & Warlord', exceptVersions: ['com2_warlord_'], realm: 'life', tooltip: 'Versions: CoM 2\nDoes not affect heroes or fantastic units.\nUnit becomes a fantastic Life creature at level 1, losing all experience.\nDoubles melee, ranged, Thrown, and both Breath strengths, and HP.\n+4 defense, +4 resistance.\nGaze strengths are unchanged.\nGrants Supernatural.' },
    { key: 'rulerOfUnderworld', label: 'Ruler of Underworld', type: 'bool', match: 'RulerOfUnderworld', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'death', tooltip: 'Versions: CoM 2 & Warlord\nGrants Wraith Form: Weapon Immunity, Non-Corporeal, and\nattacks bypass enemy Weapon Immunity.\nSuppresses only an enemy Magic/Mithril/Adamantium material\ngrant. Independent sources such as Flame Blade still bypass.\nNot modeled: religious-power generation (oracles).' },
    { key: 'mislead', label: 'Mislead', type: 'bool', match: 'Mislead', group: 'Enchantments', subgroup: 'CoM2 & Warlord', exceptVersions: ['com2_warlord_'], realm: 'death', tooltip: 'Versions: CoM 2\nAffects normal units and heroes only.\n−1 melee, −1 ranged attack, −1 defense, −1 resistance.' },
    { key: 'innerPower', label: 'Inner Power', type: 'bool', match: 'InnerPower', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'chaos', tooltip: 'Versions: CoM 2 & Warlord\nApplies only to units with Fire Immunity or Lightning Resist.\n+3 to all attack strengths (melee, ranged, thrown, breath).\n+2 defense, +2 resistance.\nNot modeled: Mountaineer/Pathfinding movement perks (Warlord).' },
    { key: 'blazingEyes', label: 'Blazing Eyes', type: 'bool', match: 'BlazingEyes', group: 'Enchantments', subgroup: 'CoM2 & Warlord', exceptVersions: ['com2_warlord_'], realm: 'chaos', tooltip: 'Versions: CoM 2\nApplies only to fantastic Chaos creatures.\nGains Doom Gaze 3, or +1 strength if it already has Doom Gaze.' },
    { key: 'reinforceMagic', label: 'Reinforce Magic', type: 'bool', match: 'ReinforceMagic', group: 'Enchantments', subgroup: 'CoM2 & Warlord', realm: 'sorcery', tooltip: 'Versions: CoM 2 & Warlord\n+2 resistance.\n+2 magical ranged attack strength, if the unit has one.' },
  ]),
  // Enchantments — Renamed in Warlord (CoM2 spells given new names in the Warlord mod;
  // the matching CoM2-named entries above are disabled when the Warlord version is selected).
  ...realmLinear([
    { key: 'apotheosis', calcKey: 'destiny', label: 'Apotheosis', type: 'bool', match: 'Apotheosis', group: 'Enchantments', subgroup: 'Renamed in Warlord', realm: 'life', tooltip: 'Versions: Warlord\nDoes not affect heroes or fantastic units.\nUnit becomes a fantastic Life creature at level 1, losing all experience.\nDoubles melee, ranged, Thrown, and both Breath strengths, and HP.\n+4 defense, +4 resistance.\nGaze strengths are unchanged.\nGrants Supernatural.\nNot modeled: No Healing removal (undead units).' },
    { key: 'liability', calcKey: 'mislead', label: 'Liability', type: 'bool', match: 'Liability', group: 'Enchantments', subgroup: 'Renamed in Warlord', realm: 'death', tooltip: 'Versions: Warlord\nAffects normal units and heroes only.\n−1 melee, −1 ranged attack, −1 defense, −1 resistance.' },
    { key: 'chaosEmbrace', calcKey: 'blazingEyes', label: 'Chaos Embrace', type: 'bool', match: 'ChaosEmbrace', group: 'Enchantments', subgroup: 'Renamed in Warlord', realm: 'chaos', tooltip: 'Versions: Warlord\nApplies only to fantastic Chaos creatures.\nGains Doom Gaze 3, or +1 strength if it already has Doom Gaze.\nNot modeled: religious-power generation, garrison Doom damage.' },
    { key: 'natureLink', calcKey: 'landLinking', label: 'Nature Link', type: 'bool', match: 'NatureLink', group: 'Enchantments', subgroup: 'Renamed in Warlord', realm: 'nature', tooltip: 'Versions: Warlord\n+1 resistance (all units).\nFantastic creatures also gain +2 defense, +2 melee, +2 breath attack.\nNot modeled: all-terrain movement.' },
  ]),
  // Enchantments — Warlord only
  { key: 'lavaSmelterWeaponImmunity', label: 'Lava Smelter: Weapon Imm.', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPermanent Mithril + Adamantium grant.\nGrants Weapon Immunity to an eligible non-fantastic unit.' },
  { key: 'lavaSmelterMissileImmunity', label: 'Lava Smelter: Missile Imm.', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPermanent Mithril + Crysx grant.\nGrants Missile Immunity to an eligible non-fantastic unit.' },
  { key: 'lavaSmelterResistElements', label: 'Lava Smelter: Resist Elem.', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPermanent Mithril + Orihalcon grant.\nGrants Resist Elements independently of Elemental Armor.' },
  { key: 'lavaSmelterElementalArmor', label: 'Lava Smelter: Elem. Armor', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPermanent Adamantium + Orihalcon grant.\nGrants Elemental Armor independently of Resist Elements;\nwhen both are present, both defense bonuses apply.' },
  { key: 'lavaSmelterFieryBlade', label: 'Lava Smelter: Fiery Blade', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPermanent Adamantium + Crysx grant.\n+3 melee, +2 Missile/Thrown, and bypasses Weapon Immunity.\nDoes not stack corresponding bonuses with Flame Blade.' },
  { key: 'godsPlayDices', label: 'Gods Play Dices: Resistance', type: 'num', min: -2, max: 2, signed: true, match: 'GodsPlayDices', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nEnter the Resistance modifier rolled for this unit at combat start.\nInteger from −2 to +2.' },
  { key: 'channeler', label: 'Marionette: Channeler owner', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\nWanderer (hero type 48) only.\nApplies the current Channeler wizard\'s Marionette transformation.\nWhen off, Wanderer receives its persistent strayed package, including Transmute Equipment, Rebuild, and Charmed.' },
  { key: 'marionetteBaseSkill', label: 'Marionette: Base skill', type: 'num', min: 0, max: 999, group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\nChanneler-owned Wanderer only.\nAdds floor(Base skill / 30) melee and ranged attack\nand floor(Base skill / 50) armor.' },
  { key: 'marionettePrimary', label: 'Marionette: Primary realm', type: 'select', options: [['nature','Nature'],['sorcery','Sorcery'],['chaos','Chaos'],['life','Life'],['death','Death']], group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\nChanneler-owned Wanderer only.\nSelects the generated magical ranged type and spell package.\nAscension adds a realm-specific general attack package.' },
  { key: 'marionetteNatureBooks', label: 'Marionette: Nature books', type: 'num', min: 0, max: 13, group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\n2+: Forester and Mountaineer. 3+: Poison Immunity.\n5+: Stoning Immunity; with Ascension, Regeneration +2.' },
  { key: 'marionetteSorceryBooks', label: 'Marionette: Sorcery books', type: 'num', min: 0, max: 13, group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\n2+: Large Shield. 3+: Missile Immunity.\n5+: Resist Magic; with Ascension, Invisibility.' },
  { key: 'marionetteChaosBooks', label: 'Marionette: Chaos books', type: 'num', min: 0, max: 13, group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\n2+: First Strike. 3+: Fire Immunity.\n5+: Lightning Resist; with Ascension, Destruction 0.' },
  { key: 'marionetteLifeBooks', label: 'Marionette: Life books', type: 'num', min: 0, max: 13, group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\n2+: Healer. 3+: Illusion Immunity.\n5+: Lucky; with Ascension, Healing Aura.' },
  { key: 'marionetteDeathBooks', label: 'Marionette: Death books', type: 'num', min: 0, max: 13, group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\n2+: Cold Immunity. 3+: Death Immunity.\n5+: Weapon Immunity; with Ascension, Life Steal −1.' },
  { key: 'marionetteAscension', label: 'Marionette: Ascension', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\nUpgrades Wanderer\'s spell and adds the primary-realm combat package.\nAlso changes spell charges to max(1, floor(primary books / 2)).' },
  { key: 'marionetteConjurer', label: 'Marionette: Conjurer', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord 1.5.12.9\nWith Ascension, replaces the primary-realm attack spell with its summon spell.\nDoes not otherwise change the one-round damage calculation.' },
  { key: 'pillarOfFaithRes', label: 'Pillar of Faith: +Res', type: 'num', match: 'PillarOfFaithRes', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Versions: Warlord\nApplies to normal units only.\nUnits trained in the city gain +1 Resistance per qualifying\nbuilding; the executing script has no cap.\nEnter the counted building total.' },
  { key: 'powerMinerals', label: 'Natural Sel.: Power minerals', type: 'num', match: 'PowerMinerals', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nApplies to normal units only.\nNatural Selection grants +1 Resistance per 10 Power from\nmineral resources near the training city.\nEnter the Resistance bonus directly.' },
  { key: 'survivalInstinctToBlock', label: 'Survival Instinct: +To Block%', type: 'num', match: 'SurvivalInstinctToBlock', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nApplies to normal units only.\nNewly trained units gain To Block from precious-metal veins:\nsilver +3%, gold +5%, gems +7%.\nEnter the To Block bonus percentage directly.' },
  ...realmLinear([
    { key: 'altarOfTheMoon', label: 'Altar of the Moon', type: 'bool', match: 'AltarOfTheMoon', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal Gnoll-race units.\nGrants Rage, Poison Immunity, and +1 Resistance.\nRanged units: +2 ranged attack.\nGnoll Hunters: Poison 2.\nGnoll Witchdoctors: Life Steal -1, replacing Poison.' },
    { key: 'altarOfTheSun', label: 'Altar of the Sun (+fig)', type: 'bool', match: 'AltarOfTheSun', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal Hawkmen-race units.\n+1 Figure.\nHoly Mother gains +1 melee instead of the figure.\nNot modeled: the defending-city High Prayer buff.' },
    { key: 'alumniOfAcademy', label: 'Academy (Alumni)', type: 'bool', match: 'AlumniOfAcademy', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to Halfling Rocs or non-Mechanical Halfling units\nwith magical ranged attacks.\n+2 Figures.' },
    { key: 'armorcladReform', label: 'Armorclad reform', type: 'bool', match: 'ArmorcladReform', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nMechanical units gain Armorclad: +6 permanent Armor.\nOther non-fantastic units gain Battle Armor: +3 Armor in combat.' },
    { key: 'ballisticsTraining', label: 'Ballistics Training', type: 'bool', match: 'BallisticsTraining', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Outlander research reform, not a cast spell.\nRegular units and Sapiens summons gain +20% Ranged,\nBreath, and Thrown To-Hit in combat.' },
    { key: 'artificer', label: 'Artificer retort', type: 'bool', match: 'Artificer', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to Mechanical units.\n+1 melee, +1 ranged, +1 armor, +2 resistance.\nGrants Magic Weapons: +10% To Hit, bypasses Weapon Immunity.' },
    { key: 'dragonMound', label: 'Dragon Mound', type: 'bool', match: 'DragonMound', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal Draconian-race units.\n+1 armor.\n+2 fire breath; creates strength 2 when absent.' },
    { key: 'energyBeamWeapons', label: 'Energy Beam Weapons', type: 'bool', match: 'EnergyBeamWeapons', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nNon-fantastic regular, Hero, and Armorclad units deal Doom\nmelee damage.\nPower Engine units with positive permanent conventional Ranged\ngain Energy Cannon: Beam, +50% ranged strength, ranged Doom,\nand ranged-only Destruction based on Ranged To-Hit.' },
    { key: 'explosive', label: 'Explosive reform', type: 'bool', match: 'ExplosiveReform', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nNon-fantastic and Sapiens units with melee or Flying gain\nBombs&Grenades: additive Thrown strength\nfloor(8 − maximum figures / 2), plus Wall Crusher.\nBlackpowder units gain +2 ranged and double Fire Breath.' },
    { key: 'favoredTerrain', label: 'Favored Terrain', type: 'bool', match: 'FavoredTerrain', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nUnit fights on its favored combat tile (set by its movement\nability: Forester, Mountaineer, Amphibious, or Pathfinding).\n+5% To Hit and +1 defense.\nTactician retort: bonus doubled, plus First Strike and Negate\nFirst Strike.' },
    { key: 'fortification', label: 'Fortification', type: 'bool', match: 'Fortification', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nDefending units inside city walls gain Large Shield:\n+3 defense vs ranged, thrown, and breath attacks.\nIf the unit already has Large Shield, it gains Missile\nImmunity instead.' },
    { key: 'heatPowerEngine', label: 'Heat Power Engine', type: 'bool', match: 'HeatPowerEngine', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nMechanical units gain the permanent Power Engine upgrade.\nPower Engine enables Magitek Engineering, Temporal Engineering,\nand Energy Beam Weapons effects.' },
    { key: 'hillfort', calcKey: 'missileImmunity', label: 'Hillfort', type: 'bool', match: 'Hillfort', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nDefending units inside city walls gain Missile Immunity.' },
    { key: 'lightningBlade', label: 'Lightning Blade', type: 'bool', match: 'LightningBlade', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies to normal units only.\nThrown attack: becomes Lightning Breath at Thrown +1 strength.\nWithout Thrown: creates or overwrites strength-1 Lightning Breath,\nwhich can coexist with conventional ranged and Fire Breath.\nThe permanent write follows Military Workshop / Rocketry.\nLightning Breath is innate and gains veterancy bonuses.\nLightning Breath is Armor Piercing.\nOpponents with Lightning Resist negate the Armor Piercing.' },
    { key: 'ludusAgoge', label: 'Ludus Agoge', type: 'bool', match: 'LudusAgoge', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal Orc-race units; Legionaries excluded.\n+1 melee, +1 ranged, +1 resistance, +1 HP per figure.\nNot modeled: the Legionary +1 Movement bonus.' },
    { key: 'magitekEngineering', label: 'Magitek Engineering', type: 'bool', match: 'MagitekEngineering', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPower Engine units gain +20% To-Defend and Large Shield.' },
    { key: 'magitekScience', label: 'Magitek Science', type: 'bool', match: 'MagitekScience', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Outlander research reform, not a cast spell.\nArmorclad units gain Resist Magic.\nThe manual and helptext also name Battle Armor, but the script\ndoes not grant it there.' },
    { key: 'malnourished', label: 'Malnourished', type: 'bool', match: 'Malnourished', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\n-1 melee attack, -2 armor.' },
    // The eight `STypeID`s at UnitCalc.CAS!NOTGOBLINCOUNT!+13..+20 "%OR (GETSTAT(UOT,STypeID,1)=52)" "%OR (GETSTAT(UOT,STypeID,1)=363)" are named in the tooltip because the
    // friendly-side scan around them (UnitCalc.CAS!NOTGOBLINCOUNT!+5..+27 "FOR N=1 TO NMAXCOMBAT;" "NEXT N;") is outside the one-attacker-one-defender
    // scope, so this control asserts the presence instead of deriving it. The names come from
    // `Unit rosters/Warlord mod unit data/UNITS.INI` sections [52] [78] [110] [117] [144]
    // [292] [357] [363], which agree with `Calculator/units_warlord.js` (F196).
    { key: 'mechanicalExpert', label: 'Mechanical Expert', type: 'bool', match: 'MechanicalExpert', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to Mechanical units.\n+20% To Hit and +10% To Block.\nSet when the friendly side holds any of: Beastmen, High Men, Klackon,\nOrc, or Xuanyuan Engineers; Dwarf Combat Engineers; Goblin Mechaniacs;\nClockwork Tinmen; or a hero with Mechanical Master.\nRebuild does not set it: the scan reads permanent unit type, which\nRebuild does not change, and it grants no Mechanical Master.\nA Rebuilt hero is not Mechanical to this bonus either: the hero\nbranch of Rebuild writes only the calculated record.\nNot modeled: the friendly-side presence scan.' },
    { key: 'militaryWorkshop', label: 'Military Workshop', type: 'bool', match: 'MilitaryWorkshop', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nEligible normal units with physical ranged, Thrown, or Fire\nBreath gain Blackpowder Weapon.\nPhysical ranged/Thrown gains Armor Piercing; if already Armor\nPiercing or Doom, ranged gains +2 and Thrown gains +4.\nFire Breath gains +4; Missile becomes a heavy projectile.\nPoison increases by 1.' },
    { key: 'militaryDrilling', label: 'Military Drilling', type: 'bool', match: 'MilitaryDrilling', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Outlander research reform, not a cast spell.\nNew non-fantastic units gain permanent Discipline.\nNot modeled: Mechanical units heal 3 HP per turn below half Health.' },
    { key: 'motherFungus', label: 'Mother Fungus', type: 'bool', match: 'MotherFungus', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal Goblin-race units.\n+2 melee, +2 ranged, and +10% To Block.\n+1 Poison (grants Poison 1 if the unit has none).\nNot modeled: the x2 ability-charge bonus.' },
    { key: 'pneumaReactor', label: 'Pneuma Reactor', type: 'bool', match: 'PneumaReactor', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nNon-fantastic regular, Hero, and Armorclad units gain Life\nSteal at −floor(current Resistance / 2).\nStacks with an existing negative Life Steal modifier.' },
    { key: 'poolOfRepentance', label: 'Pool of Repentance', type: 'bool', match: 'PoolOfRepentance', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal Rakhshasa-race units.\n+1 armor and +1 resistance.' },
    { key: 'psychoConverter', label: 'Psycho Converter', type: 'bool', match: 'PsychoConverter', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nNon-fantastic regular, Hero, and Armorclad units gain To-Hit\nand To-Defend equal to\nfloor(current Resistance × Level / 2)%.' },
    { key: 'radio', label: 'Radio', type: 'bool', match: 'Radio', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Outlander research reform, not a cast spell.\nRegular units and Sapiens summons gain +10% To-Hit,\n+10% To-Defend, and +1 Resistance in combat.' },
    { key: 'rocketry', label: 'Rocketry', type: 'bool', match: 'Rocketry', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nEligible normal units with physical ranged, Thrown, or Fire\nBreath gain Blackpowder Weapon.\nIts combat effects are identical to Military Workshop.' },
    { key: 'sanctaBasilica', label: 'Sancta Basilica', type: 'bool', match: 'SanctaBasilica', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nApplies only to normal High Men-race units.\nAll trained units gain +3 Resistance.\nClergy, Crusaders, and Paladins also gain Sanctify.\nCrusaders also gain Lucky; Paladins also gain Magic Immunity.\nNot modeled: improved Exorcise (Clergy), the defending-city\nTrue Light buff.' },
    { key: 'temporalEngineering', label: 'Temporal Engineering', type: 'bool', match: 'TemporalEngineering', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nPower Engine units gain Haste.\nSailing Power Engine units also gain Flying and Illusion Immunity.' },
    { key: 'uphillBattle', label: 'Uphill Battle (AI unit)', type: 'bool', match: 'UphillBattle', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Versions: Warlord\nCheck this for an AI-controlled unit fighting the human player.\n+10% To Hit, +10% To Defend, and +1 Resistance.' },
    { key: 'xenopsychology', label: 'Xenopsychology', type: 'bool', match: 'Xenopsychology', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Outlander research reform, not a cast spell.\nRegular units and Sapiens summons gain +1 Resistance in combat.' },
    { key: 'xenoveterinary', label: 'Xenoveterinary', type: 'bool', match: 'Xenoveterinary', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Outlander wizard only.\nFantastic creatures gain +10% To-Hit and +25% HP\n(minimum +1) in combat.\nArmorclad access through Obsolescence Rearmament is not modeled.' },
    { key: 'outlanderWizard', label: 'Outlander wizard', type: 'bool', match: 'OutlanderWizard', group: 'Enchantments', subgroup: 'Warlord only', tooltip: 'Owner is an Outlander wizard.\nRequired for every Outlander reform condition in this panel.' },
    // Warlord's Flame Blade is an arcane unit ability rather than the wizard spell above, but it
    // sets the same record flag and runs the same block, so the two controls — disjoint by
    // version, one visible in each — name one `calcKey`, as `disciplineWarlord` does. A second
    // key would make the spell's control a Warlord derivation input it is not (F118).
    { key: 'flameBladeWarlord', calcKey: 'flameBlade', label: 'Flame Blade', type: 'bool', match: 'FlameBlade', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nArcane unit ability, not a wizard spell.\nBypasses Weapon Immunity.\n+3 melee, +2 missile/thrown, +1 fire breath.\nStacks with Fiery Blade or Fiery Fury — shared bonuses do not double; the only added bonus is +1 fire breath.' },
    { key: 'rebuild', label: 'Rebuild', type: 'bool', match: 'Rebuild', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nA non-hero becomes Mechanical; a hero does not, because the hero\nbranch writes only the calculated record.\n+2 melee, +2 armor.\nGrants Death Immunity, Illusion Immunity, and Armor Piercing.' },
    { key: 'spiritLink', label: 'Spirit Link', type: 'bool', match: 'SpiritLink', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: "Versions: Warlord\n+2 Resistance.\nSet fantastic near the start of the stat recalculation and cleared\nagain near the end of it.\nAnything read in between sees a fantastic creature, so a regular unit\ngains the fantastic-creature bonuses of Nature Link, Survival Instinct\nand Xenoveterinary, and Nausea does not apply to it.\nAnything read afterwards sees a non-fantastic one: Exorcise cannot\nbanish it and a fantastic creature can earn experience levels (not\nunder Apotheosis), while Liability, Rust and an enemy's Blood Lust\nreach it and the Leadership aura replaces the Soul Linker aura.\nEither way its attacks bypass Weapon Immunity: the magic-weapon flag is\nset while the unit is fantastic and the clearing write does not undo it." },
    { key: 'luckyStar', label: 'Lucky Star aura', type: 'bool', match: 'LuckyStar', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nSet when any friendly unit in the combat has Lucky Star.\nEvery friendly unit gains +1 melee, ranged, thrown, and breath attack.\n+1 Armor, +1 Resistance. Multiple copies do not stack.\nThe enchanted unit itself also gains Lucky — tick Lucky for it.' },
    { key: 'rally', label: 'Rally', type: 'bool', match: 'Rally', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\n+2 Resistance.' },
    { key: 'nausea', label: 'Nausea', type: 'bool', match: 'Nausea', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nDoes not affect fantastic creatures or units with Magic Immunity.\n−10% To Hit, −10% To Defend.' },
    { key: 'disheartenProphecy', label: 'Dishearten Prophesy', type: 'bool', match: 'DisheartenProphecy', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\n−2 Resistance.' },
    { key: 'divineProtection', label: 'Divine Protection', type: 'bool', match: 'DivineProtection', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Versions: Warlord\nGrants Lucky and Death Immunity.\n+10% To Hit, +10% To Block, +1 Resistance.' },
    { key: 'angelicGuardians', label: 'Angelic Guardians', type: 'bool', match: 'AngelicGuardians', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Warlord Life Rare global enchantment.\nGrants Exorcise −0 to a base non-Fantastic unit, even after a\nFantastic conversion; a current Life/Sanctified unit gets −1.\nAn existing Exorcise is improved on any unit: −2 stronger, or\n−3 stronger for Life/Sanctified.\nCreated-undead defenders suffer an additional −3.' },
    { key: 'eyeOfHeaven', label: 'Eye of Heaven', type: 'bool', match: 'EyeOfHeaven', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Versions: Warlord\nGrants True Sight (Illusion Immunity).\nThe opposing unit loses all gaze attacks (Doom, Death,\nStoning, hidden gaze).' },
    { key: 'sanctify', label: 'Sanctify', type: 'bool', match: 'Sanctify', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Versions: Warlord\nUnit becomes Life realm.\nNon-hero Clergy also become Fantastic; heroes do not.\nNot modeled: Cleric casting-skill bonus.' },
    { key: 'zeal', label: 'Zeal', type: 'bool', match: 'Zeal', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nArcane unit ability, not a wizard spell.\nGrants First Strike and Negate First Strike.' },
    { key: 'hierophany', label: 'Hierophany', type: 'bool', match: 'Hierophany', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Versions: Warlord\nHalves the cursed unit\'s Defense (rounded down).\nStrips all immunities, Lightning Resist, Negate First Strike,\nMerging, and Teleporting. Other stripped mobility perks are not modeled.' },
    { key: 'pillarOfFaithLucky', label: 'Pillar of Faith: Lucky', type: 'bool', match: 'PillarOfFaithLucky', group: 'Enchantments', subgroup: 'Warlord only', realm: 'life', tooltip: 'Versions: Warlord\nGrants Lucky: +10% To Hit, +10% To Block, +1 Resistance.' },
    { key: 'shadowStrike', label: 'Shadow Strike', type: 'bool', match: 'ShadowStrike', group: 'Enchantments', subgroup: 'Warlord only', realm: 'death', tooltip: 'Versions: Warlord\nAdds a Thrown attack at 1 + 1/3 of melee (rounded down).\nA unit with an existing Thrown attack adds that to its Thrown.' },
    { key: 'revenant', label: 'Revenant', type: 'bool', match: 'Revenant', group: 'Enchantments', subgroup: 'Warlord only', realm: 'death', tooltip: 'Versions: Warlord\nUnit becomes undead: grants Death, Cold, and Illusion Immunity.\nReplaces Death Touch with 0 on melee and Thrown: per attacker\nfigure, defender resists or one figure dies.\nDoes not apply to Breath or ranged attacks.\nNot modeled: Regeneration.' },
    { key: 'vampirism', label: 'Vampirism', type: 'bool', match: 'Vampirism', group: 'Enchantments', subgroup: 'Warlord only', realm: 'death', tooltip: 'Versions: Warlord\nUnit becomes undead and gains Blood Sucker.\nHalf the combined Thrown, Fire Breath, and Lightning Breath\nstrength transfers to melee (truncated).\nEach positive source attack drops to strength 1.' },
    { key: 'soulFlay', label: 'Soul Flay', type: 'bool', match: 'SoulFlay', group: 'Enchantments', subgroup: 'Warlord only', realm: 'death', tooltip: 'Versions: Warlord\nDoes not affect fantastic creatures.\nPer experience level: −1 melee, −1 ranged, −2 armor, −2 resistance.\nRecruit: −1 / −1 / −2 / −2. Elite: −4 / −4 / −8 / −8.' },
    { key: 'plague', label: 'Plague', type: 'bool', match: 'Plague', group: 'Enchantments', subgroup: 'Warlord only', realm: 'death', tooltip: 'Versions: Warlord\n−3 melee, −3 ranged, −3 armor, −6 Resistance, −10% To Hit.' },
    { key: 'berserkWarlord', label: 'Berserk (Warlord)', type: 'bool', match: 'Berserk', group: 'Enchantments', subgroup: 'Warlord only', realm: 'arcane', tooltip: 'Versions: Warlord\nArcane Troll Medicineman unit ability, not a wizard spell.\n+15% To Hit.\n−1 armor.\nNot modeled: combat movement.' },
    { key: 'blazeOfGlory', label: 'Blaze of Glory', type: 'bool', match: 'BlazeOfGlory', group: 'Enchantments', subgroup: 'Warlord only', realm: 'chaos', tooltip: 'Versions: Warlord\nDoes not affect heroes.\nGains melee equal to its current Armor, then Armor becomes 0.\nLater aura bonuses can add Armor afterward.\nRanged strength is added to the Thrown attack; Ranged becomes 0.\nGrants Armor Piercing and Wall Crusher, and loses First Strike.\nNot modeled: ammo loss, wall breaking.' },
    { key: 'fieryFury', label: 'Fiery Fury', type: 'bool', match: 'FieryFury', group: 'Enchantments', subgroup: 'Warlord only', realm: 'chaos', tooltip: 'Versions: Warlord\nBase non-Fantastic units: gain Fiery Blade, plus +2 boulder.\nThey bypass Weapon Immunity.\nBase Fantastic creatures: gain First Strike.\nBecome Chaos creatures unless undead, Apotheosis, or Sanctify.\nBonuses except boulder are not cumulative with Flame Blade or Fiery Blade.' },
    { key: 'insulation', label: 'Insulation', type: 'bool', match: 'Insulation', group: 'Enchantments', subgroup: 'Warlord only', realm: 'chaos', tooltip: 'Versions: Warlord\nGrants Fire Immunity, Cold Immunity, and Lightning Resist.\nImmune: Fire Breath, Immolation, Wall of Fire, cold attacks.\nNegates the Armor Piercing of incoming Lightning Breath.' },
    { key: 'beatOfSwiftness', label: 'Beat of Swiftness', type: 'bool', match: 'BeatOfSwiftness', group: 'Enchantments', subgroup: 'Warlord only', realm: 'chaos', tooltip: 'Versions: Warlord\nSubtracts current Armor / 10, rounded to nearest (ties to even).\nNot modeled: combat movement.' },
    { key: 'rust', label: 'Rust', type: 'bool', match: 'Rust', group: 'Enchantments', subgroup: 'Warlord only', realm: 'chaos', tooltip: 'Versions: Warlord\nDoes not affect fantastic creatures.\nMagic and orihalcon weapons stripped (unit reverts to regular weapons).\n−3 melee and physical ranged (missile/boulder).\nThrown attacks eliminated for the rest of combat.\nLarge Shield eliminated for the rest of combat.\nNot modeled: loss of permanent enchantments.' },
    { key: 'wallOfFireBoost', label: 'Wall of Fire: garrison', type: 'bool', match: 'WallOfFireBoost', group: 'Enchantments', subgroup: 'Warlord only', realm: 'chaos', tooltip: 'Wall of Fire (Warlord Chaos Common city enchantment) garrison buff.\nDefending units gain +1 melee, +1 physical ranged (missile/boulder), and +1 thrown attack.\nThose attacks bypass Weapon Immunity.\nHeroes are included; a permanently fantastic creature gains nothing.\nThe fire-line damage to attackers crossing the wall is the separate global Wall of Fire toggle.' },
    { key: 'colossalStrength', label: 'Colossal Strength', type: 'bool', match: 'ColossalStrength', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\n+1 plus 40% of current melee strength (rounded down).\nScales the strength after other bonuses and penalties, not the base.\nSame bonus to physical ranged and thrown attacks.' },
    { key: 'venom', label: 'Venom', type: 'bool', match: 'Venom', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\n+1 Poison (grants Poison 1 if the unit has none).\nGrants Poison Immunity.' },
    // The Transmute Equipment cast (F256.2). `spells.ini` `[264]`, Realm 1 (Nature),
    // `EnchantmentID=69`, `SpellTypeGroup=15` — the group that refuses a permanently Fantastic
    // target. Warlord alone: the base CoM2 script set names `EncTransmuteEquipment` nowhere and
    // its `spells.ini` has no such spell. `DisAbil.CAS` prints the hero result as "Body
    // Augmented", which is why the label names both. The cast's own write and the seven other
    // engine grant paths for the same permanent flag are enumerated once, on the
    // `transmuteEquipment` entry in `stats_origins.js`.
    { key: 'transmuteEquipment', label: 'Transmute Equipment', type: 'bool', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nDoes not affect permanently fantastic units.\nHeroes gain Body Augmented: +2 melee, +2 ranged, +2 armor,\nand +1 Resistance.\nEvery other unit is re-equipped instead: Adamantium weapons\nand Orihalcon armor, replacing the materials it carried.\nNot modeled: overland recast and dispel protection.' },
    { key: 'coal', label: 'Natural Sel.: Coal', type: 'bool', match: 'NaturalSelectionCoal', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nApplies to normal units only.\n+1 melee attack.' },
    { key: 'iron', label: 'Natural Sel.: Iron', type: 'bool', match: 'NaturalSelectionIron', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nApplies to normal units only.\n+1 Armor.' },
    { key: 'wildGame', label: 'Natural Sel.: Wild game', type: 'bool', match: 'NaturalSelectionWildGame', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nApplies to normal units only.\n+1 to ranged attacks (physical and magical ranged; not thrown or breath).\nNot modeled: Forester.' },
    { key: 'nightshade', label: 'Natural Sel.: Nightshade count', type: 'num', min: 0, max: 99, match: 'NaturalSelectionNightshade', group: 'Enchantments', subgroup: 'Warlord only', realm: 'nature', tooltip: 'Versions: Warlord\nApplies to normal units only.\n+1 Resistance per Nightshade in range. If Power minerals are\nalso present, this later script write replaces their bonus.' },
    { key: 'planewalking', calcKey: 'teleporting', label: 'Planewalking', type: 'bool', match: 'Planewalking', group: 'Enchantments', subgroup: 'Warlord only', realm: 'sorcery', tooltip: 'Versions: Warlord\nGrants Teleporting.' },
    { key: 'temporalTwist', label: 'Temporal Twist', type: 'bool', match: 'TemporalTwist', group: 'Enchantments', subgroup: 'Warlord only', realm: 'sorcery', tooltip: 'Versions: Warlord\nDoes not affect units with Magic Immunity.\nStrips First Strike, Negate First Strike, and Teleporting.\nThe later Tactician step can restore strike flags from Favored\nTerrain or Non-Corporeal, but not from stripped Teleporting.\nNot modeled: movement penalty.' },
    { key: 'greatUnbinding', label: 'Great Unbinding', type: 'bool', match: 'GreatUnbinding', group: 'Enchantments', subgroup: 'Warlord only', realm: 'sorcery', tooltip: 'Versions: Warlord\nReaches a Fantastic unit, and also an Undead, Revenant, Vampirism\nor Chaos Channels unit.\nA Spirit Linked unit is exempt outright.\n−20% To Hit.\n−20% To Block.\n−2 Resistance.\nNot modeled: Confusion, and the exemption for a unit whose own\nwizard also holds Great Unbinding (the page has no input for it).' },
  ]),
];
